// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(uint256 val) public {
        // initialize the contract, sealing configuration
        c.Initialized();
        uint256 before = c.MinSum();
        bool ok;
        // after initialization SetMinSum must revert for ANY input value
        try c.SetMinSum(val) { ok = true; } catch { ok = false; }
        assertTrue(!ok && c.MinSum() == before);
    }
}
